#include <DHT.h>
#include <math.h>

// =====================================================
// SMART LIGHTING SYSTEM - ARDUINO UNO R3
// =====================================================

// -------------------- SENSOR PINS --------------------

const byte LDR_PIN = A0;
const byte LM35_PIN = A1;
const byte AIR_PIN = A2;
const byte DHT_PIN = A3;

#define DHTTYPE DHT11
DHT dht(DHT_PIN, DHTTYPE);

// HC-SR04 Zone 1
const byte TRIG1 = 2;
const byte ECHO1 = 4;

// HC-SR04 Zone 2
const byte TRIG2 = 7;
const byte ECHO2 = 8;

// HC-SR04 Zone 3
const byte TRIG3 = 12;
const byte ECHO3 = 13;

// -------------------- LED OUTPUTS --------------------

// Zone 1
const byte WHITE1 = 3;
const byte YELLOW1 = 5;

// Zone 2
const byte WHITE2 = 6;
const byte YELLOW2 = 9;

// Zone 3
const byte WHITE3 = 10;
const byte YELLOW3 = 11;


// =====================================================
// SETTINGS
// =====================================================

// Distance settings (cm)
const float DISTANCE_START_DIM = 60.0;
const float DISTANCE_OFF = 20.0;

// HC-SR04 maximum echo wait
const unsigned long ECHO_TIMEOUT = 30000UL;

// Time between sonar measurements
const unsigned long SONAR_GAP_MS = 60;

// Sensor update intervals
const unsigned long DHT_INTERVAL = 2000UL;
const unsigned long SERIAL_INTERVAL = 500UL;

// Ambient brightness
const int MIN_BRIGHTNESS = 20;

// Temperature effect
const float TEMP_REFERENCE = 15.0;
const float TEMP_WHITE_SHIFT_MAX = 0.30;
const float TEMP_YELLOW_SHIFT_MAX = 0.30;

// Air sensor / potentiometer on A2
const int AIR_THRESHOLD = 150;
const float AIR_WHITE_SHIFT_MAX = 0.40;

// Humidity effect
const float HUMIDITY_START = 20.0;
const float HUMIDITY_FULL = 50.0;
const float HUMIDITY_MAX_DIM = 0.10;
const float HUMIDITY_COLOR_SHIFT = 0.40;

// Smoothing
const float LDR_FILTER_ALPHA = 0.20;
const float DISTANCE_FILTER_ALPHA = 0.45;
const float PWM_FILTER_ALPHA = 0.25;


// =====================================================
// GLOBAL VARIABLES
// =====================================================

float temperature = 25.0;
float humidity = 50.0;

int airValue = 0;
int ldrRaw = 0;

float ldrFiltered = 512.0;

float distance1 = 999.0;
float distance2 = 999.0;
float distance3 = 999.0;

// Consecutive invalid readings per sensor
byte invalidCount[3] = {0, 0, 0};

float pwmFiltered[6] = {0, 0, 0, 0, 0, 0};
int targetPWM[6] = {0, 0, 0, 0, 0, 0};

unsigned long lastDHTRead = 0;
unsigned long lastSerialPrint = 0;

bool dhtReadStarted = false;


// =====================================================
// PWM FREQUENCY
// =====================================================

void configurePWMFrequency() {

  // Timer1: pins 9 and 10
  // Phase-correct 8-bit PWM, approximately 3.92 kHz

  TCCR1A = (TCCR1A & 0b11111100) | 0b00000001;
  TCCR1B = (TCCR1B & 0b11100111) | 0b00000010;

  // Timer2: pins 3 and 11
  // Phase-correct 8-bit PWM, approximately 3.92 kHz

  TCCR2A = (TCCR2A & 0b11111100) | 0b00000001;
  TCCR2B = (TCCR2B & 0b11110000) | 0b00000010;

  // Timer0 remains unchanged for millis(), delay()
  // and timing functions.
}


// =====================================================
// HC-SR04 DISTANCE READING
// =====================================================

float readDistance(byte trigPin, byte echoPin) {

  digitalWrite(trigPin, LOW);
  delayMicroseconds(3);

  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  unsigned long duration =
      pulseIn(echoPin, HIGH, ECHO_TIMEOUT);

  // No echo received
  if (duration == 0) {
    return -1.0;
  }

  float distance = duration * 0.0343 / 2.0;

  // Reject out-of-range measurements
  if (distance < 2.0 || distance > 400.0) {
    return -1.0;
  }

  return distance;
}


// =====================================================
// DISTANCE FILTER AND ERROR HANDLING
// =====================================================

float updateDistanceFilter(
    float previousDistance,
    float newDistance,
    byte sensorIndex) {

  // If a reading is invalid, briefly retain the
  // previous measurement to avoid sudden flicker.
  if (newDistance < 0.0) {

    if (invalidCount[sensorIndex] < 255) {
      invalidCount[sensorIndex]++;
    }

    // After repeated failures, mark the reading unknown.
    // Unknown distance defaults to full brightness.
    if (invalidCount[sensorIndex] >= 3) {
      return 999.0;
    }

    return previousDistance;
  }

  // Reset failure counter on a valid echo
  invalidCount[sensorIndex] = 0;

  // First valid measurement
  if (previousDistance >= 900.0) {
    return newDistance;
  }

  // Smooth the measurement
  return previousDistance +
      DISTANCE_FILTER_ALPHA *
      (newDistance - previousDistance);
}


// =====================================================
// DISTANCE TO BRIGHTNESS
// =====================================================

float distanceBrightnessFactor(float distance) {

  // No valid measurement yet
  if (distance >= 900.0) {
    return 1.0;
  }

  // Full brightness outside the dimming zone
  if (distance >= DISTANCE_START_DIM) {
    return 1.0;
  }

  // Turn this zone off when an object is very close
  if (distance <= DISTANCE_OFF) {
    return 0.0;
  }

  // Linear dimming between 60 cm and 20 cm
  float factor =
      (distance - DISTANCE_OFF) /
      (DISTANCE_START_DIM - DISTANCE_OFF);

  return constrain(factor, 0.0, 1.0);
}


// =====================================================
// LDR AMBIENT LIGHT
// =====================================================

int readAmbientBrightness() {

  ldrRaw = analogRead(LDR_PIN);

  ldrFiltered +=
      LDR_FILTER_ALPHA *
      (ldrRaw - ldrFiltered);

  // Assumes higher LDR ADC reading means brighter
  // ambient light, so the lamps dim as the room brightens.
  float brightness =
      255.0 - ldrFiltered * (255.0 / 1023.0);

  brightness = constrain(
      brightness,
      (float)MIN_BRIGHTNESS,
      255.0
  );

  return (int)(brightness + 0.5);
}


// =====================================================
// LM35 TEMPERATURE SENSOR
// =====================================================

float readTemperatureC() {

  long total = 0;

  for (byte i = 0; i < 5; i++) {
    total += analogRead(LM35_PIN);
  }

  float raw = total / 5.0;
  float voltage = raw * (5.0 / 1023.0);

  // LM35: approximately 10 mV per degree Celsius
  return voltage * 100.0;
}


// =====================================================
// TEMPERATURE COLOR EFFECT
// =====================================================

float calculateTemperatureShift() {

  if (temperature > TEMP_REFERENCE) {

    float effect =
        (temperature - TEMP_REFERENCE) / 25.0;

    effect = constrain(effect, 0.0, 1.0);

    return effect * TEMP_WHITE_SHIFT_MAX;
  }

  if (temperature < TEMP_REFERENCE) {

    float effect =
        (TEMP_REFERENCE - temperature) / 15.0;

    effect = constrain(effect, 0.0, 1.0);

    return -(effect * TEMP_YELLOW_SHIFT_MAX);
  }

  return 0.0;
}


// =====================================================
// AIR QUALITY INPUT EFFECT
// =====================================================

float calculateAirShift() {

  if (airValue <= AIR_THRESHOLD) {
    return 0.0;
  }

  float effect =
      (float)(airValue - AIR_THRESHOLD) /
      (1023.0 - AIR_THRESHOLD);

  effect = constrain(effect, 0.0, 1.0);

  return effect * AIR_WHITE_SHIFT_MAX;
}


// =====================================================
// HUMIDITY EFFECT
// =====================================================

float calculateHumidityLevel() {

  float level =
      (humidity - HUMIDITY_START) /
      (HUMIDITY_FULL - HUMIDITY_START);

  return constrain(level, 0.0, 1.0);
}


// =====================================================
// SMOOTH PWM OUTPUTS
// =====================================================

void updateSmoothPWM() {

  const byte ledPins[6] = {
    WHITE1, YELLOW1,
    WHITE2, YELLOW2,
    WHITE3, YELLOW3
  };

  for (byte i = 0; i < 6; i++) {

    float difference =
        targetPWM[i] - pwmFiltered[i];

    pwmFiltered[i] +=
        PWM_FILTER_ALPHA * difference;

    if (fabs(difference) < 0.8) {
      pwmFiltered[i] = targetPWM[i];
    }

    int output = (int)(pwmFiltered[i] + 0.5);
    output = constrain(output, 0, 255);

    analogWrite(ledPins[i], output);
  }
}


// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(9600);

  pinMode(TRIG1, OUTPUT);
  pinMode(ECHO1, INPUT);

  pinMode(TRIG2, OUTPUT);
  pinMode(ECHO2, INPUT);

  pinMode(TRIG3, OUTPUT);
  pinMode(ECHO3, INPUT);

  pinMode(WHITE1, OUTPUT);
  pinMode(YELLOW1, OUTPUT);

  pinMode(WHITE2, OUTPUT);
  pinMode(YELLOW2, OUTPUT);

  pinMode(WHITE3, OUTPUT);
  pinMode(YELLOW3, OUTPUT);

  digitalWrite(TRIG1, LOW);
  digitalWrite(TRIG2, LOW);
  digitalWrite(TRIG3, LOW);

  dht.begin();

  configurePWMFrequency();

  // Initialize all lights off
  analogWrite(WHITE1, 0);
  analogWrite(YELLOW1, 0);

  analogWrite(WHITE2, 0);
  analogWrite(YELLOW2, 0);

  analogWrite(WHITE3, 0);
  analogWrite(YELLOW3, 0);

  Serial.println(F("Smart Lighting System"));
  Serial.println(F("Initialization complete"));
  Serial.println(F("Open Serial Monitor at 9600 baud"));
}


// =====================================================
// MAIN LOOP
// =====================================================

void loop() {

  unsigned long now = millis();

  // ---------------------------------------------------
  // 1. DHT11: read every two seconds
  // ---------------------------------------------------

  if (!dhtReadStarted ||
      now - lastDHTRead >= DHT_INTERVAL) {

    lastDHTRead = now;
    dhtReadStarted = true;

    float newHumidity = dht.readHumidity();

    if (!isnan(newHumidity) &&
        newHumidity >= 0.0 &&
        newHumidity <= 100.0) {

      humidity = newHumidity;
    }
  }

  // ---------------------------------------------------
  // 2. Read temperature and air input
  // ---------------------------------------------------

  temperature = readTemperatureC();
  airValue = analogRead(AIR_PIN);

  // ---------------------------------------------------
  // 3. Read ambient light
  // ---------------------------------------------------

  int ambientBrightness = readAmbientBrightness();

  // ---------------------------------------------------
  // 4. Read three ultrasonic sensors
  // ---------------------------------------------------

  float newDistance1 = readDistance(TRIG1, ECHO1);

  distance1 = updateDistanceFilter(
      distance1, newDistance1, 0
  );

  delay(SONAR_GAP_MS);

  float newDistance2 = readDistance(TRIG2, ECHO2);

  distance2 = updateDistanceFilter(
      distance2, newDistance2, 1
  );

  delay(SONAR_GAP_MS);

  float newDistance3 = readDistance(TRIG3, ECHO3);

  distance3 = updateDistanceFilter(
      distance3, newDistance3, 2
  );

  // ---------------------------------------------------
  // 5. Calculate sensor effects
  // ---------------------------------------------------

  float temperatureShift =
      calculateTemperatureShift();

  float airShift =
      calculateAirShift();

  float humidityLevel =
      calculateHumidityLevel();

  float humidityShift =
      humidityLevel * HUMIDITY_COLOR_SHIFT;

  float humidityBrightnessFactor =
      1.0 - humidityLevel * HUMIDITY_MAX_DIM;

  // ---------------------------------------------------
  // 6. Calculate complementary color ratios
  // ---------------------------------------------------

  float whiteRatio =
      0.50 +
      temperatureShift +
      airShift -
      humidityShift;

  whiteRatio = constrain(whiteRatio, 0.05, 0.95);

  float yellowRatio = 1.0 - whiteRatio;

  // ---------------------------------------------------
  // 7. Calculate brightness targets
  // ---------------------------------------------------

  float baseBrightness =
      ambientBrightness * humidityBrightnessFactor;

  int whiteTarget =
      (int)(baseBrightness * whiteRatio + 0.5);

  int yellowTarget =
      (int)(baseBrightness * yellowRatio + 0.5);

  whiteTarget = constrain(whiteTarget, 0, 255);
  yellowTarget = constrain(yellowTarget, 0, 255);

  // ---------------------------------------------------
  // 8. Apply independent distance dimming per zone
  // ---------------------------------------------------

  float factor1 = distanceBrightnessFactor(distance1);
  float factor2 = distanceBrightnessFactor(distance2);
  float factor3 = distanceBrightnessFactor(distance3);

  targetPWM[0] = (int)(whiteTarget * factor1 + 0.5);
  targetPWM[1] = (int)(yellowTarget * factor1 + 0.5);

  targetPWM[2] = (int)(whiteTarget * factor2 + 0.5);
  targetPWM[3] = (int)(yellowTarget * factor2 + 0.5);

  targetPWM[4] = (int)(whiteTarget * factor3 + 0.5);
  targetPWM[5] = (int)(yellowTarget * factor3 + 0.5);

  // ---------------------------------------------------
  // 9. Update all six LED outputs smoothly
  // ---------------------------------------------------

  updateSmoothPWM();

  // ---------------------------------------------------
  // 10. Serial Monitor diagnostics
  // ---------------------------------------------------

  now = millis();

  if (now - lastSerialPrint >= SERIAL_INTERVAL) {

    lastSerialPrint = now;

    Serial.println(F("\n------ SENSOR STATUS ------"));

    Serial.print(F("LDR raw: "));
    Serial.println(ldrRaw);

    Serial.print(F("LDR filtered: "));
    Serial.println(ldrFiltered, 1);

    Serial.print(F("Ambient brightness: "));
    Serial.println(ambientBrightness);

    Serial.print(F("Temperature C: "));
    Serial.println(temperature, 1);

    Serial.print(F("Humidity %: "));
    Serial.println(humidity, 1);

    Serial.print(F("Humidity level: "));
    Serial.println(humidityLevel, 2);

    Serial.print(F("Air analog value: "));
    Serial.println(airValue);

    Serial.print(F("Sensor 1 distance cm: "));
    if (newDistance1 < 0) {
      Serial.print(F("NO ECHO"));
    } else {
      Serial.print(newDistance1, 1);
    }
    Serial.print(F(" | Filtered: "));
    Serial.println(distance1, 1);

    Serial.print(F("Sensor 2 distance cm: "));
    if (newDistance2 < 0) {
      Serial.print(F("NO ECHO"));
    } else {
      Serial.print(newDistance2, 1);
    }
    Serial.print(F(" | Filtered: "));
    Serial.println(distance2, 1);

    Serial.print(F("Sensor 3 distance cm: "));
    if (newDistance3 < 0) {
      Serial.print(F("NO ECHO"));
    } else {
      Serial.print(newDistance3, 1);
    }
    Serial.print(F(" | Filtered: "));
    Serial.println(distance3, 1);

    Serial.print(F("White ratio: "));
    Serial.println(whiteRatio, 2);

    Serial.print(F("Yellow ratio: "));
    Serial.println(yellowRatio, 2);

    Serial.print(F("Zone 1 PWM: "));
    Serial.print((int)pwmFiltered[0]);
    Serial.print(F(", "));
    Serial.println((int)pwmFiltered[1]);

    Serial.print(F("Zone 2 PWM: "));
    Serial.print((int)pwmFiltered[2]);
    Serial.print(F(", "));
    Serial.println((int)pwmFiltered[3]);

    Serial.print(F("Zone 3 PWM: "));
    Serial.print((int)pwmFiltered[4]);
    Serial.print(F(", "));
    Serial.println((int)pwmFiltered[5]);
  }
}
